// Guards: G4 test governance (CLAUDE.md, Platform Admin 26 Oct 2026 09:36 and 10:49): every spec names what it guards, nothing carried skipped, phone runs only where needed and never silently lost, live-acting deployed specs held unless switched on
// CF-247 S120. Register: admin docs/platform/TEST-REGISTER.md, generated by scripts/test-register.mjs and updated in the same PR as any
// test it lists. Record: admin docs/platform/ui-audit/2026-10-26-test-governance.md.
import { test, expect } from '@playwright/test'
import fs from 'node:fs'
import { specInfo } from '../../scripts/test-register.mjs'

const DIR = 'tests/uat'
const specs = fs.readdirSync(DIR).filter((f) => f.endsWith('.spec.mjs')).map((f) => specInfo(f, fs.readFileSync(`${DIR}/${f}`, 'utf8')))

test('no anonymous tests: every spec starts with the rule or decision it guards', () => {
  for (const s of specs) {
    expect(fs.readFileSync(`${DIR}/${s.file}`, 'utf8').startsWith('// Guards: '), s.file).toBe(true)
    expect(s.guards.length, `${s.file}: say what it guards`).toBeGreaterThanOrEqual(20)
    expect(s.tests.length, `${s.file} has no tests`).toBeGreaterThan(0)
  }
})

test('nothing carried skipped: no unconditional skip, fixme or only; a skip for a missing environment belongs to the deployed track', () => {
  for (const s of specs.filter((x) => x.id !== 'cf-247-s120-test-governance-contract')) {  // this spec names the patterns it forbids
    const src = fs.readFileSync(`${DIR}/${s.file}`, 'utf8')
    expect(src, `${s.file}: test.skip(...) / test.fixme(...) as a test`).not.toMatch(/(?<![\w.])test\.(skip|fixme|only)\(\s*['"`]/)
    expect(src, `${s.file}: test.skip(true, ...)`).not.toMatch(/test\.skip\(\s*true\b/)
    // a spec on node:test is loaded by Playwright but never counted or failed on (6 such tests were red unseen until 26 Oct 2026)
    expect(src, `${s.file}: uses node:test`).not.toMatch(/from\s*['"]node:test['"]/)
    if (/test\.skip\(/.test(src) && /UAT_BASE_URL/.test(src)) expect(s.deployed, `${s.file}: skips without the deployed environment but is not @deployed`).toBe(true)
  }
})

test('the phone viewport runs only responsive-tagged tests and the deployed gate; standing rules keep one guard each', () => {
  const cfg = fs.readFileSync('playwright.config.mjs', 'utf8')
  expect(cfg).toMatch(/name: 'chromium-mobile',\n\s+use: \{ \.\.\.devices\['Pixel 7'\] \},\n\s+grep: \/@responsive\|@deployed\/,/)
  // the legacy release baseline is guarded once (S70), not repeated in other specs
  const legacy = specs.filter((s) => /LEGACY_BASELINE\)\.toBe\('2\.15\.78'\)|historyVersion\)\.toBe\('2\.15\.78'\)/.test(fs.readFileSync(`${DIR}/${s.file}`, 'utf8')))
  expect(legacy.map((s) => s.id)).toEqual(['cf-247-s70-patch-scripts-retired'])
})

test('the register generator lists every spec with its category', () => {
  const kinds = new Set(specs.map((s) => s.kind))
  for (const k of kinds) expect(['rule', 'regression', 'deployed']).toContain(k)
  expect(specs.filter((s) => s.kind === 'rule').map((s) => s.id).sort()).toEqual([
    'cf-247-institution-type-contract', 'cf-247-s120-test-governance-contract', 'cf-247-s32-controls-in-settings-contract', 'cf-247-s42-housekeeping-contract',
    'cf-247-s57-consumer-api-frozen', 'cf-247-s70-patch-scripts-retired', 'cf-247-website-api-v2-contract', 'm245-release-history-v21575-persistence-contract',
    'release-notes-deployed'])
})

test('phone screens stay phone tests: the three operated screens are responsive-tagged, run on the phone project only and assert phone width', () => {
  const cfg = fs.readFileSync('playwright.config.mjs', 'utf8')
  expect(cfg).toMatch(/name: 'chromium-desktop',\n\s+use: \{ \.\.\.devices\['Desktop Chrome'\], viewport: \{ width: 1440, height: 1100 \} \},\n\s+grepInvert: \/@responsive\/,/)
  const src = fs.readFileSync(`${DIR}/cf-247-s121-phone-screens-contract.spec.mjs`, 'utf8')
  expect(src).toContain("test.describe('phone screens @responsive', () => {")
  for (const screen of ['Course catalogue list', 'Course detail blade', 'Layer 4 Review']) {
    const i = src.indexOf(`test('${screen}:`)
    expect(i, `${screen} phone test`).toBeGreaterThan(0)
    const body = src.slice(i, src.indexOf('\n  })\n', i))
    expect(body, `${screen} asserts phone width first`).toContain('await atPhoneWidth(page)')
  }
  expect(src).toContain('const PHONE_MAX = 480')
})

test('live-acting deployed specs are tagged and held unless the switch is on (weekly run and deployed-uat)', () => {
  const ACTS = [/functions\/v1\/layer1-operations-control/, /\bapply\.click\(\)/, /\bparse\.click\(\)/, /name:'Validate'\}\)\.click\(\)/, /name:'Arrange sections'/, /survive reload and logout/]
  for (const s of specs.filter((x) => x.deployed)) {
    const src = fs.readFileSync(`${DIR}/${s.file}`, 'utf8')
    if (ACTS.some((r) => r.test(src))) expect(src, `${s.file} acts on the live site but has no @live-acting test`).toContain('@live-acting')
  }
  const weekly = fs.readFileSync('.github/workflows/deployed-weekly.yml', 'utf8')
  expect(weekly).toContain("LIVE_ACTING: ${{ inputs.live_acting || vars.DEPLOYED_WEEKLY_LIVE_ACTING || 'off' }}")
  expect(weekly).toMatch(/cron: "17 18 \* \* 0"/)
  expect(weekly.match(/--grep @deployed --grep-invert @live-acting --project=chromium-(desktop|mobile)/g)).toHaveLength(2)
  const uat = fs.readFileSync('.github/workflows/deployed-uat.yml', 'utf8')
  expect(uat.match(/--grep-invert @live-acting --pass-with-no-tests --project=chromium-(desktop|mobile)/g)).toHaveLength(2)
})
